#!/usr/bin/env bash
# Generated by agent-harness-tui (create-only; edit freely).
# Manages agent.db next to this script. completed.log is the source of
# truth for completed instructions: this script only appends to it.
# Requires the sqlite3 CLI. Author: $AGENT_DB_ACTOR (default: agent).
set -euo pipefail

dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
db="$dir/agent.db"
log="$dir/completed.log"
actor=${AGENT_DB_ACTOR:-agent}

usage() {
  cat <<'EOF'
usage: agent-db.sh init | verify | schema | timestamp | reconcile
       agent-db.sh backlog-list
       agent-db.sh backlog-add <title> [description]
       agent-db.sh backlog-complete <id>
       agent-db.sh instruction-list
       agent-db.sh instruction-show <uuid>
       agent-db.sh instruction-upsert <uuid> <title>
       agent-db.sh instruction-complete <uuid> <summary>
EOF
}

fail() { printf 'error: %s\n' "$1" >&2; exit 1; }
# Quote via a variable: bash 3.2 (macOS) keeps backslashes in `${1//\'/...}`.
q() { local sq="'"; printf "'%s'" "${1//$sq/$sq$sq}"; }
now() { date '+%Y-%m-%d %H:%M:%S %z'; }
trim() { local s=$1; s=${s#"${s%%[![:space:]]*}"}; printf '%s' "${s%"${s##*[![:space:]]}"}"; }

command -v sqlite3 >/dev/null || fail "sqlite3 CLI not found; install it to use this script"

sql() { sqlite3 -bail "$@"; }

init_schema() {
  sql "$db" >/dev/null <<'SQL'
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS backlog (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'created',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_by TEXT
);
CREATE TABLE IF NOT EXISTS instructions (
  uuid TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'created',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_backlog_status ON backlog(status);
CREATE INDEX IF NOT EXISTS idx_instructions_status ON instructions(status);
SQL
}

# Marks every instruction listed in completed.log as completed.
reconcile() {
  init_schema
  [[ -f "$log" ]] || return 0
  local line uuid rest summary ts t
  t=$(now)
  {
    echo '.timeout 5000'
    echo 'BEGIN IMMEDIATE;'
    while IFS= read -r line || [[ -n "$line" ]]; do
      [[ -z "${line//[[:space:]]/}" || "$line" == \#* ]] && continue
      [[ "$line" == *'|'*'|'* ]] || fail "invalid completed.log line: $line"
      uuid=$(trim "${line%%|*}")
      rest=${line#*|}
      ts=$(trim "${rest##*|}")
      summary=$(trim "${rest%|*}")
      printf "INSERT INTO instructions(uuid,title,status,created_at,updated_at,created_by,updated_by) VALUES(%s,%s,'completed',%s,%s,'completed.log','completed.log') ON CONFLICT(uuid) DO UPDATE SET status='completed',updated_at=%s,updated_by='completed.log' WHERE status<>'completed';\n" \
        "$(q "$uuid")" "$(q "$summary")" "$(q "$ts")" "$(q "$ts")" "$(q "$t")"
    done < "$log"
    echo 'COMMIT;'
  } | sql "$db"
}

one_line() { [[ -n "$2" && "$2" != *'|'* && "$2" != *$'\n'* && "$2" != *$'\r'* ]] || fail "$1 must be one non-empty line without '|'"; }

cmd=${1:-}
case "$cmd" in
  init|reconcile) reconcile ;;
  schema) init_schema; sql "$db" .schema ;;
  timestamp) now ;;
  verify)
    reconcile
    sql -header -column "$db" "PRAGMA integrity_check; SELECT 'backlog' AS tbl, status, COUNT(*) AS rows FROM backlog GROUP BY status UNION ALL SELECT 'instructions', status, COUNT(*) FROM instructions GROUP BY status;"
    ;;
  backlog-list)
    reconcile
    sql -header -column "$db" "SELECT id,title,description,created_at,status FROM backlog WHERE status='created' ORDER BY id;"
    ;;
  backlog-add)
    [[ $# -eq 2 || $# -eq 3 ]] || { usage; exit 2; }
    reconcile
    t=$(now)
    desc=NULL; [[ $# -eq 3 ]] && desc=$(q "$3")
    sql "$db" "INSERT INTO backlog(title,description,status,created_at,updated_at,created_by,updated_by) VALUES($(q "$2"),$desc,'created',$(q "$t"),$(q "$t"),$(q "$actor"),$(q "$actor")); SELECT last_insert_rowid();"
    ;;
  backlog-complete)
    [[ $# -eq 2 && "$2" =~ ^[0-9]+$ ]] || { usage; exit 2; }
    reconcile
    n=$(sql "$db" "UPDATE backlog SET status='completed',updated_at=$(q "$(now)"),updated_by=$(q "$actor") WHERE id=$2; SELECT changes();")
    [[ "$n" == 1 ]] || fail "backlog id not found: $2"
    ;;
  instruction-list)
    reconcile
    sql -header -column "$db" "SELECT uuid,title,status,created_at,updated_at FROM instructions ORDER BY created_at,uuid;"
    ;;
  instruction-show)
    [[ $# -eq 2 ]] || { usage; exit 2; }
    reconcile
    sql -header -column "$db" "SELECT uuid,title,status,created_at,updated_at,created_by,updated_by FROM instructions WHERE uuid=$(q "$2");"
    ;;
  instruction-upsert)
    [[ $# -eq 3 ]] || { usage; exit 2; }
    one_line uuid "$2"; one_line title "$3"
    reconcile
    t=$(now)
    sql "$db" "INSERT INTO instructions(uuid,title,status,created_at,updated_at,created_by,updated_by) VALUES($(q "$2"),$(q "$3"),'created',$(q "$t"),$(q "$t"),$(q "$actor"),$(q "$actor")) ON CONFLICT(uuid) DO UPDATE SET title=excluded.title,updated_at=excluded.updated_at,updated_by=excluded.updated_by WHERE status<>'completed';"
    ;;
  instruction-complete)
    [[ $# -eq 3 ]] || { usage; exit 2; }
    one_line uuid "$2"; one_line summary "$3"
    reconcile
    if [[ -f "$log" ]]; then
      while IFS= read -r line || [[ -n "$line" ]]; do
        [[ "$line" == *'|'* && "$(trim "${line%%|*}")" == "$2" ]] && fail "already in completed.log: $2"
      done < "$log"
    fi
    # Append only; never rewrite existing lines.
    [[ -s "$log" && -n "$(tail -c1 "$log")" ]] && printf '\n' >> "$log"
    printf '%s | %s | %s\n' "$2" "$3" "$(now)" >> "$log"
    reconcile
    ;;
  *) usage; exit 2 ;;
esac
